#!/usr/bin/env python3
"""Render real MenuScreen and AddonScreen with explicit platform, inventory and transport doubles."""
from pathlib import Path
import argparse,subprocess,os,json,yaml
p=argparse.ArgumentParser()
for key in ('java-home','minecraft','gson','output'):p.add_argument('--'+key,type=Path,required=True)
