(out/'help.json').write_text(json.dumps(yaml.safe_load((root/'server/src/main/resources/menus/help.yml').read_text()),ensure_ascii=False))
src=out/'adapter';classes=out/'classes';classes.mkdir(exist_ok=True)
for f in src.rglob('*Probe.java'):f.unlink()
