f=src/'net/minecraft/client/gui/GuiGraphicsExtractor.java';s=f.read_text().replace('public final java.util.List<String> texts=', 'public record PaintedText(String text,double x,double y){}public final java.util.List<PaintedText> positions=new ArrayList<>();public final java.util.List<String> texts=').replace('texts.add(s);f.draw', 'var point=new java.awt.geom.Point2D.Double(x,y);g.getTransform().transform(point,point);positions.add(new PaintedText(s,point.x,point.y));texts.add(s);f.draw');f.write_text(s)
