put('net/minecraft/client/gui/screens/inventory/ContainerScreen.java','''package net.minecraft.client.gui.screens.inventory;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;import net.minecraft.world.inventory.ChestMenu;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.input.MouseButtonEvent;public class ContainerScreen extends Screen{protected final ChestMenu menu;protected int leftPos=30,topPos=30,imageWidth=176,imageHeight=222,titleLabelX=8,titleLabelY=6,inventoryLabelX=8,inventoryLabelY=126;protected Component playerInventoryTitle=Component.literal("Инвентарь");public int releases;public ContainerScreen(ChestMenu menu,Object inventory,Component title){super(title);this.menu=menu;}public ChestMenu getMenu(){return menu;}protected void extractLabels(GuiGraphicsExtractor g,int x,int y){}@Override public boolean mouseReleased(MouseButtonEvent e){releases++;return false;}@Override public void onClose(){net.minecraft.client.Minecraft.getInstance().gui.setScreen(null);}}''')
