put('net/minecraft/client/Minecraft.java','''package net.minecraft.client;import net.minecraft.client.gui.screens.Screen;import net.minecraft.world.inventory.*;import net.minecraft.resources.Identifier;import java.util.*;public class Minecraft{private static final Minecraft INSTANCE=new Minecraft();public static Minecraft getInstance(){return INSTANCE;}public final net.minecraft.client.gui.Font font=new net.minecraft.client.gui.Font();public final Gui gui=new Gui();public final Player player=new Player();public final GameMode gameMode=new GameMode();public Object getSoundManager(){return this;}public static class Gui{public Screen screen;public void setScreen(Screen s){screen=s;}public Screen screen(){return screen;}}public static class Player{public ChestMenu containerMenu;public Object getInventory(){return this;}public void sendOverlayMessage(net.minecraft.network.chat.Component c){}public Skin getSkin(){return new Skin();}}public static class Skin{public Skin body(){return this;}public Identifier texturePath(){return Identifier.parse("minecraft:skin");}}public static class GameMode{public record Click(int container,int slot,int button,ContainerInput mode){}public final List<Click> clicks=new ArrayList<>();public void handleContainerInput(int container,int slot,int button,ContainerInput mode,Player p){clicks.add(new Click(container,slot,button,mode));}}}''')
